  infile datalines dsd truncover;
  input HHID $ RGN $ IMTH $ UHRS PWGT;
  datalines;
  HHI0001,0,201703,618.72,211.54
  HHI0002,0,201703,563.74,269.69
  HHI0003,0,201703,718.93,886.18
  HHI0004,1,201703,528.41,842.54
  ;
run;

data d2;
  length HHID $10 RGN $1 LFST $2 INCB $2 PRXF $1;
  infile datalines dsd truncover;
  input HHID $ RGN $ LFST $ INCB $ PRXF $;
  datalines;
  HHI0001,0,I,P,R
  HHI0002,0,N,E,R
  HHI0003,0,A,N,A
  HHI0004,1,R,A,N
