%macro prcstep5(p=, lb=work, thr=0);
proc sort data=d1 out=_sd1; by HHID RGN; run;
proc sort data=d2 out=_sd2; by HHID RGN; run;
data _t1;
  merge _sd1(in=i1) _sd2(in=i2);
  by HHID RGN;
  if i1;
  if UHRS ge &thr;
  if IMTH = '' then IMTH = "&dt";
run;

proc summary data=_t1 nway;
  class RGN;
  var UHRS PWGT;
  output out=agg1(drop=_type_ _freq_) sum=;
run;
data _t2; set _t1; run;

proc sql noprint;
  create table _t3 as
    select a.*, b.PRXF as PRXF_b
    from _t2 a left join _sd2 b
      on a.HHID = b.HHID;
quit;

proc transpose data=_t3 out=_x4 prefix=v;
  by HHID;
  var UHRS;
run;
data _t4; set _t3; run;

data _t5;
  set _t4;
  if UHRS > 0 then UHRSR = round(100*UHRS/UHRS, 0.01);
  else UHRSR = .;
run;

data &lb..o3;
  set _t5;
run;
%mend prcstep5;

%prcstep5(p=&dt);

